<div class="page-heading"><div><h1>Sparepart</h1></div><a class="button" href="<?=e(url('part-new'))?>"><?=mdi('plus')?> Tambah sparepart</a></div><section class="panel"><form class="filter-bar" method="get"><input type="hidden" name="page" value="parts"><label class="search-field"><span class="sr-only">Cari sparepart</span><input name="q" value="<?=e($q)?>" maxlength="150" placeholder="Cari SKU atau nama sparepart…"></label><label class="filter-check"><input type="checkbox" name="low" value="1" <?=$low?'checked':''?>> Stok menipis</label><label class="filter-check"><input type="checkbox" name="deleted" value="1" <?=$deleted?'checked':''?>> Dihapus</label><button class="button secondary"><?=mdi('magnify')?> Cari</button><a class="reset-link" href="<?=e(url('parts'))?>">Reset</a></form><?php if(!$parts): ?><div class="empty"><span><?=mdi('package-variant-closed')?></span><h3>Sparepart belum tersedia</h3><p>Tambah komponen baru atau sesuaikan pencarian Anda.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>SKU / NAMA</th><th>STOK</th><th>MINIMUM</th><th>HARGA BELI</th><th>HARGA JUAL</th><th></th></tr></thead><tbody><?php foreach($parts as $part): ?><tr><td><a class="table-primary" href="<?=e(url('part',['id'=>$part['id']]))?>"><?=e($part['name'])?></a><small><?=e($part['sku'])?></small></td><td><strong><?=e($part['stock'].' '.$part['unit'])?></strong><?php if($part['stock']<=$part['minimum_stock']): ?><small class="stock-low">Stok menipis</small><?php endif; ?></td><td><?=e($part['minimum_stock'])?></td><td><?=e(money($part['purchase_price']))?></td><td><?=e(money($part['sale_price']))?></td><td><a class="row-arrow" aria-label="Detail <?=e($part['name'])?>" href="<?=e(url('part',['id'=>$part['id']]))?>"><?=mdi('arrow-top-right')?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php pagination($p,count($parts),'parts',['q'=>$q,'low'=>$low?'1':'0','deleted'=>$deleted?'1':'0']); ?></section>
